#!/usr/bin/env python3
"""Tests for the inert JetSpec promotion checklist / ADR."""

from __future__ import annotations

import pathlib
import sys
import unittest

HERE = pathlib.Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import validate_promotion_checklist as validator


CHECKLIST_PATH = HERE / "jetspec_promotion_checklist.md"


class PromotionChecklistTests(unittest.TestCase):
    def test_promotion_checklist_validator_passes(self) -> None:
        result = validator.validate_checklist(CHECKLIST_PATH)

        self.assertTrue(result["ok"], result["errors"])
        self.assertEqual(result["phase_order"], ["P0", "P1", "P2", "P3", "P4", "P5", "P6"])

    def test_only_approved_p5_hook_sets_are_listed(self) -> None:
        text = CHECKLIST_PATH.read_text(encoding="utf-8")

        for path_token in validator.REQUIRED_FORBIDDEN_PATHS:
            self.assertIn(path_token, text)
        self.assertIn("| P5A production hook set | validation-only candidate approved | P5A |", text)
        self.assertIn("| P5B private target-tap hook set | side-channel candidate approved | P5B |", text)
        self.assertIn("| P5C speculative type hook set | fail-closed parser candidate approved | P5C |", text)
        self.assertIn("| P5D target-tap ingestion hook set | non-drafting runtime slice approved | P5D |", text)
        self.assertIn("| P5E runtime-state hook set | state-only runtime slice approved | P5E |", text)
        self.assertIn("| P5F binding-preflight hook set | preflight-only runtime slice approved | P5F |", text)
        self.assertIn("| P5N transaction-plan scaffold hook set | non-drafting transaction scaffold approved | P5N |", text)
        self.assertIn("| P5O pre-round snapshot hook set | non-drafting snapshot descriptor approved | P5O |", text)
        self.assertIn("| P5P transient-reservation descriptor hook set | descriptor-only reservation slice approved | P5P |", text)
        self.assertIn("| P5Q tree-build descriptor hook set | descriptor-only tree-build slice approved | P5Q |", text)
        self.assertIn("| P5X root-only runtime tree hook set | default-off one-node tree ABI approved | P5X |", text)
        self.assertIn("| P5Y root-only verify-mask runtime hook set | default-off one-entry root mask ABI approved | P5Y |", text)
        self.assertIn("| P5Z root-anchor accept-path runtime hook set | default-off root-anchor accept ABI approved | P5Z |", text)
        self.assertIn("| P5AA root-token-commit no-op runtime hook set | default-off root token-commit no-op ABI approved | P5AA |", text)
        self.assertIn("| P5AB-P5AD root no-op tail readiness hook set | default-off root no-op tail readiness approved | P5AB-P5AD |", text)
        self.assertIn("| P5AE synthetic top-k tree ABI hook set | default-off synthetic top-k tree ABI approved | P5AE |", text)
        self.assertIn("| P5AF synthetic top-k verify-mask ABI hook set | default-off synthetic top-k verify-mask ABI approved | P5AF |", text)
        self.assertIn("| P5AG synthetic top-k accept-boundary ABI hook set | default-off synthetic top-k accept-boundary ABI approved | P5AG |", text)
        self.assertIn("| P5AH draft-head top-k readiness descriptor | inert experiments-only readiness, no production hook approval | P5AH |", text)
        self.assertIn("| non-P5A/P5B `src/models/*.cpp` | forbidden | tree-runtime approval |", text)
        self.assertIn("non-P5C/P5D/P5E/P5F/P5N/P5O/P5P/P5Q/P5R/P5S/P5T/P5U/P5V/P5W/P5X/P5Y/P5Z/P5AA/P5AB-P5AD/P5AE/P5AF/P5AG `common/` files | forbidden | next runtime approval", text)
        self.assertIn("`tools/server/server-context.cpp` JetSpec model-only binding | allowed only with `ctx_dft=nullptr`, no draft context, and no graph execution | P5F model-only binding", text)
        self.assertIn("other `tools/server/` behavior/routes | forbidden | runtime approval", text)
        self.assertIn("`ggml/src/` | forbidden | P6", text)

