    def test_next_allowed_work_requires_tree_runtime_approval(self) -> None:
        text = CHECKLIST_PATH.read_text(encoding="utf-8")

        self.assertIn("P5N consumed the first explicit tree-runtime approval", text)
        self.assertIn("P5O consumed the next approval as a bounded pre-round snapshot descriptor only", text)
        self.assertIn("P5P consumed the next approval as a descriptor-only transient reservation intent", text)
        self.assertIn("P5Q consumed the next approval as a descriptor-only tree-build intent", text)
        self.assertIn("P5X consumed the next approval as a default-off root-only runtime tree ABI object", text)
        self.assertIn("P5Y consumed the next approval as a default-off root-only verify-mask ABI object", text)
        self.assertIn("P5Z consumed the next approval as a default-off root-anchor accept-path ABI object", text)
        self.assertIn("P5AA consumed the next approval as a default-off root-token-commit no-op ABI object", text)
        self.assertIn("P5AB-P5AD consumed the next approval as default-off root no-op tail readiness objects", text)
        self.assertIn("P5AE/P5AF/P5AG consumed the next approval as default-off synthetic top-k tree, ancestor-mask, and accept-boundary ABI objects", text)
        self.assertIn("P5AH consumed no production approval", text)
        self.assertIn("accept_boundary_candidate_nodes=2", text)
        self.assertIn("actual_verified_logits_rows=0", text)
        self.assertIn("planned_draft_head_logits_rows=1", text)
